Here is the C++ code to find the shortest path from the origin to all other vertices using Dijkstra's algorithm:

```c++
#include <bits/stdc++.h>

using namespace std;

struct Edge {
  int src, dest, weight;
};

struct Graph {
  int V;
  vector<Edge> edges;

  Graph(int V) {
    this->V = V;
  }

  void addEdge(int src, int dest, int weight) {
    edges.push_back({src, dest, weight});
  }
};

void dijkstra(Graph &g, int src, vector<int> &dist) {
  dist.assign(g.V, INT_MAX);
  dist[src] = 0;

  set<pair<int, int>> pq;
  pq.insert({0, src});

  while (!pq.empty()) {
    int u = pq.begin()->second;
    pq.erase(pq.begin());

    for (Edge &e : g.edges) {
      if (dist[e.dest] > dist[u] + e.weight) {
        pq.erase({dist[e.dest], e.dest});
        dist[e.dest] = dist[u] + e.weight;
        pq.insert({dist[e.dest], e.dest});
      }
    }
  }
}

int main() {
  int V, E;
  cin >> V >> E;

  Graph g(V);

  for (int i = 0; i < E; i++) {
    int u, v, w;
    cin >> u >> v >> w;
    g.addEdge(u, v, w);
  }

  int src;
  cin >> src;

  vector<int> dist;
  dijkstra(g, src, dist);

  for (int i = 0; i < V; i++) {
    cout << dist[i] << " ";
  }

  cout << endl;

  return 0;
}
```

