#include <stdio.h>

// Define the structure for a linked list node
typedef struct Node {
    int data;
    struct Node *next;
} Node;

// Function to reverse the linked list in-place
void reverseList(Node **head) {
    Node *prev = NULL;
    Node *current = *head;
    Node *next = NULL;

    while (current != NULL) {
        // Store next node
        next = current->next;

        // Reverse the link
        current->next = prev;

        // Move pointers one position ahead
        prev = current;
        current = next;
    }

    // Update head pointer
    *head = prev;
}

// Function to add a new node at the beginning of the list
Node *addNode(Node *head, int data) {
    Node *newNode = (Node *) malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = head;

    return newNode;
}

// Function to print the linked list
void printLinkedList(Node *head) {
    Node *temp = head;
    while (temp) {
        printf("%d->", temp->data);
        temp = temp->next;
    }
    printf("NULL");
}

int main() {
    // Create a linked list
    Node *head = NULL;

    // Add some values
    head = addNode(head, 1);
    head = addNode(head, 2);
    head = addNode(head, 3);
    head = addNode(head, 4);

    printf("Original Linked List: ");
    printLinkedList(head);

    // Reverse the linked list
    reverseList(&head);

    printf("\nReversed Linked List: ");
    printLinkedList(head);

    return 0;
}

